/** Effects grouped by their `category`, preserving order. */
export function effectsByCategory(effects = EFFECTS) {
  const groups = new Map();
  for (const e of effects) {
    if (!groups.has(e.category)) groups.set(e.category, []);
    groups.get(e.category).push(e);
  }
  return groups;
}

/** The CDP programs an effect needs loaded (spectral effects also need pvoc;
 *  derive-based effects also need the programs listed in `effect.needs`). */
export function programsFor(effect) {
  const base = effect.domain === 'spectral' ? ['pvoc', effect.program] : [effect.program];
  return effect.needs ? [...new Set([...base, ...effect.needs])] : base;
}

/**
 * The range a parameter may actually take, given what its siblings are set to.
 *
 * Some CDP constraints couple parameters and a fixed min/max cannot express
 * them: a spatialisation centre must name one of the output channels, `isolate`
 * needs its minimum segment longer than twice the splice, `distort omit` needs
 * A below B. Declaring the full span leaves the UI offering values the program
 * rejects — which is exactly how a bad value reaches CDP.
 *
 * A parameter may therefore carry `minOf`/`maxOf`: each a function of the other
 * parameter values, returning the bound implied by them. The result is
 * intersected with the static `min`/`max`, which remain the absolute limits, so
 * a parameter without them behaves exactly as before.
 *
 * The other axis is the *source*. Where a program derives a limit from the
 * infile's duration — `extend zigzag` needs its output longer than its input,
 * `sfecho` its delay at least the source length — the parameter carries
 * `srcMin`/`srcMax`, and `opts.src` supplies `{ dur, srate, chans }`. These
 * *replace* the curated `min`/`max` (a bound that tracks the source cannot be
 * intersected with a constant and stay useful), but only when a source is
 * actually known: with no `opts.src` — a headless caller, an MCP catalog
 * listing, a doc renderer — the static numbers stand and nothing changes.
 *
 * `opts.unlocked` widens the span to the program's own limits for a consumer
 * that has chosen to leave the curated range (see `hardMin`/`hardMax` on Param).
 * The source-dependent engine limits (`srcHardMin`/`srcHardMax`) and sibling
 * bounds are deliberately still applied: curated bounds are taste, but these
 * encode constraints CDP genuinely rejects, so unlocking must not reopen them.
 *
 * A source shorter than the effect's `minSrcDur` has no valid parameter set at
 * all — check that before calling: the collapse below would hand back a single
 * value that looks usable while violating the constraint it encodes.
 *
 * @param {object} p       a parameter descriptor
 * @param {Record<string, number|string>} [values]  the sibling values
 * @param {{unlocked?: boolean, src?: {dur:number, srate?:number, chans?:number}}} [opts]
 * @returns {{min:number, max:number}}
 */
export function paramRange(p, values = {}, opts = {}) {
  const src = knownSource(opts.src);
  const bound = (fn, ...args) => { const v = Number(fn(...args)); return Number.isFinite(v) ? v : null; };
  const fromSrc = (fn) => (src && typeof fn === 'function' ? bound(fn, src, values) : null);
  // The source-relative span where one is declared and a source is known; the
  // curated span otherwise.
  const sMin = fromSrc(p.srcMin), sMax = fromSrc(p.srcMax);
  let min = sMin != null ? sMin : p.min;
  let max = sMax != null ? sMax : p.max;
  // Unlocked, open out to whatever engine limit has been recorded — without
  // pulling the span back inside a source-relative bound that is itself the
  // engine's (zigzag's output floor is the source duration at any lock state).
  if (opts.unlocked) {
    if (p.hardMin != null) min = Math.min(min, p.hardMin);
    if (p.hardMax != null) max = Math.max(max, p.hardMax);
  }
  if (typeof p.minOf === 'function') { const v = bound(p.minOf, values); if (v != null) min = Math.max(min, v); }
  if (typeof p.maxOf === 'function') { const v = bound(p.maxOf, values); if (v != null) max = Math.min(max, v); }
  // Unlike srcMin/srcMax, these are never slider curation: they are the
  // source-dependent limits enforced by CDP and therefore apply at both lock
  // states. Apply them after widening so unlocking cannot discard them.
  const shMin = fromSrc(p.srcHardMin), shMax = fromSrc(p.srcHardMax);
  if (shMin != null) min = Math.max(min, shMin);
  if (shMax != null) max = Math.min(max, shMax);
  // Over-constrained (e.g. splice turned right up): collapse to a single usable
  // value rather than handing back an inverted range. The floor that won may
  // itself sit past an engine limit (cantor's hole floor on a short file with a
  // long splice runs past its 99% ceiling), so the collapsed value is kept
  // inside whatever engine limits are recorded — CDP would reject it otherwise.
  if (max < min) {
    let v = min;
    if (p.hardMax != null) v = Math.min(v, p.hardMax);
    if (shMax != null) v = Math.min(v, shMax);
    if (p.hardMin != null) v = Math.max(v, p.hardMin);
    if (shMin != null) v = Math.max(v, shMin);
    min = max = v;
  }
  return { min, max };
}

/**
 * The source a range may be measured against, or null when none is known. A
 * source is known only when its duration is a finite number: a placeholder
 * (`{ dur: null }`) or a duration still in string form must not be mistaken
 * for a 0 s file, and the `src*` closures do arithmetic on `dur` directly.
 */
function knownSource(src) {
  return src && typeof src.dur === 'number' && Number.isFinite(src.dur) ? src : null;
}

/**
 * The value a parameter should start at for a given source.
 *
 * Mirrors CDP's own `INITIALISE_DEFAULT_VALUES` (dev/cdp2k/tklib1.c), which
 * seeds e.g. zigzag's window end from the infile duration and its output from
 * twice that. Falls back to the static `default` when the parameter declares no
 * `srcDefault` or no source is known, and is always clamped into the range the
 * same source implies.
 *
 * `values` must carry the *sibling* values the range is measured against: a
 * bound coupled to another parameter (zigzag's minzig must fit twice inside
 * its window `end`) is silently skipped when that sibling is absent, and the
 * result can then violate it. Resolve a whole effect with {@link defaultsFor},
 * which settles the coupling for you; call this directly only with a complete
 * `values`.
 *
 * @param {object} p
 * @param {{dur:number, srate?:number, chans?:number}|null} [src]
 * @param {Record<string, number|string>} [values]  the sibling values
 * @returns {number|string}  a choices parameter returns its value string as-is
 */
export function paramDefaultFor(p, src = null, values = {}) {
  // A choices parameter has no numeric span to clamp into (and its default is
  // often a string token, e.g. an FFT size).
  if (p.choices) return p.default;
  const known = knownSource(src);
  let v = p.default;
  if (known && typeof p.srcDefault === 'function') {
    const d = Number(p.srcDefault(known));
    if (Number.isFinite(d)) v = d;
  }
  const { min, max } = paramRange(p, values, { src: known });
  return Math.min(max, Math.max(min, v));
}

/**
 * Every parameter's starting value for a given source, settled together.
 *
 * Defaults are coupled: zigzag's `minzig` is bounded by its window `end`, whose
 * own default is the source duration, so resolving the parameters one at a
 * time in declaration order can leave an early one clamped against a sibling
 * that has not been resolved yet. This seeds every parameter with its static
 * default, then re-resolves them all with {@link paramDefaultFor} until nothing
 * moves — the same fixed point a UI's refresh loop reaches, made explicit.
 *
 * Values in `given` are taken as-is and never re-derived — the parameters the
 * caller has already chosen, with the rest filled in around them. That is how
 * {@link applyEffect} completes a partial `values`.
 *
 * With no `src`, the static defaults come back (clamped into their static span,
 * which they already satisfy).
 *
 * @param {object} effect  an entry from EFFECTS
 * @param {{dur:number, srate?:number, chans?:number}|null} [src]
 * @param {Record<string, number|string>} [given]  values to hold fixed
 * @returns {Record<string, number|string>}
 */
export function defaultsFor(effect, src = null, given = {}) {
  const params = effect.params || [];
  const fixed = new Set(Object.keys(given).filter((k) => given[k] != null));
  const values = Object.fromEntries(params.map((p) => [p.name, fixed.has(p.name) ? given[p.name] : p.default]));
  // Two passes settle every coupling in the catalog today; the cap only guards
  // against a future pair of bounds that chase each other.
  for (let pass = 0, moved = true; moved && pass < 8; pass++) {
    moved = false;
    for (const p of params) {
      if (fixed.has(p.name)) continue;
      const v = paramDefaultFor(p, src, values);
      if (v !== values[p.name]) { values[p.name] = v; moved = true; }
    }
  }
  return values;
}

/**
 * Build the concrete argument list from an effect template and parameter values.
 * '$SR' (used by generators) resolves to `sampleRate` — either as the whole
 * token (a positional rate) or embedded in one (a flag, e.g. '-s$SR'); effects
 * have none.
 */
export function buildArgs(effect, values = {}, sampleRate = 44100) {
  return effect.args.map((a) => {
    if (a === '$IN' || a === '$OUT') return a;
    if (typeof a === 'string' && a.includes('$SR')) return a.replace('$SR', String(sampleRate));
    if (a && typeof a === 'object' && a.p != null) {
      const v = values[a.p];
      const s = String(v != null ? v : paramDefault(effect, a.p));
      return a.flag ? a.flag + s : s;
    }
    return a;
  });
}

function paramDefault(effect, name) {
  const p = (effect.params || []).find((x) => x.name === name);
  return p ? p.default : '';
}

/**
 * Apply a catalog effect to a WAV byte array and return the processed WAV.
 * Handles spectral (pvoc) wrapping and mono-only programs (per-channel split),
 * preserving channel count for stereo/multichannel sources. Throws when the
 * chain produces no output, or output containing no audio frames.
 *
 * @param {import('./index.js').CDP} cdp
 * @param {object} effect  an entry from EFFECTS
 * @param {Record<string,number|string>} values  current parameter values
 * @param {Uint8Array} srcWav
 * @returns {Promise<Uint8Array>}
 */
export async function applyEffect(cdp, effect, values, srcWav, extra = {}) {
  const result = await runEffect(cdp, effect, values, srcWav, extra);
  // A chain can "succeed" — every program exits 0, every intermediate file
  // non-empty — yet synthesise zero sample frames (e.g. stretch.time driven far
  // below its declared minimum leaves pvoc synth a header-only WAV), so the
  // finished result is checked for actual audio, not just bytes.
  if (result && Array.isArray(result.outputs)) {
    // Multi-output effects: drop header-only files the same way runEffect drops
    // zero-length ones, and fail only when no file with audio remains.
    const outputs = [];
    const names = [];
    result.outputs.forEach((b, i) => {
      if (wavFrameCount(b) > 0) { outputs.push(b); names.push(result.names[i]); }
    });
    if (!outputs.length) throw noFramesError(effect.id);
    return { outputs, names };
  }
  return requireFrames(result, effect.id);
}

async function runEffect(cdp, effect, values, srcWav, extra) {
  // The source's own duration gates the run and completes the values. An entry
  // whose `minSrcDur`/`maxSrcDur` the source falls outside has no valid
  // settings at all, so refuse it here with a plain message rather than let CDP
  // report a baffling range error. Parameters the caller left out take the
  // default *for this source* (defaultsFor) — the static default is the value
  // for an unknown source, and for a source-relative parameter it is often
  // outside the engine's range (zigzag's output must outlast a 5 s input; its
  // static default is 2 s).
  const src = sourceContext(srcWav, extra);
  const tooShort = effect.minSrcDur != null && src.dur < effect.minSrcDur;
  const tooLong = effect.maxSrcDur != null && src.dur > effect.maxSrcDur;
  if (tooShort || tooLong) {
    throw new Error(`${effect.id}: the source is ${src.dur.toFixed(3)} s but this effect needs one `
      + (tooShort ? `at least ${effect.minSrcDur} s long` : `no longer than ${effect.maxSrcDur} s`)
      + ' — no parameter settings are valid for it.');
  }
  const vals = defaultsFor(effect, src, values || {});

  // Effects with a custom multi-step chain (e.g. pitch-data autotune) own their
  // whole processing path. (Breakpoint envelopes aren't threaded through these.)
  if (effect.pipeline) return effect.pipeline(cdp, srcWav, vals);

  // Breakpoint envelopes: any parameter can be supplied as a time-varying
  // envelope instead of a constant, via `extra.brk = { paramName: "t v\n..." }`.
  // Each becomes a /brk_<name>.brk file staged into MEMFS, and the parameter's
  // value is replaced by that path so CDP reads it as a breakpoint table.
  const brk = extra.brk || {};
  const brkInputs = {};
  for (const name of Object.keys(brk)) {
    if (brk[name] == null || brk[name] === '') continue;
    const path = `/brk_${name}.brk`;
    brkInputs[path] = typeof brk[name] === 'string' ? new TextEncoder().encode(brk[name]) : brk[name];
    vals[name] = path; // buildArgs emits the path (with the flag prefix if the param is flagged)
  }

  const args = buildArgs(effect, vals);
  // Effects that read a text data file either generate it from the parameters
  // (`data`, referenced as '$DATA') or derive it from the input by running CDP
  // programs (`derive`, e.g. pitch extraction). We stage the result into MEMFS.
  const staticData = effect.data ? effect.data(vals) : undefined;

  // Mixfile chain (multimix/newmix, panorama): stage several inputs, run a
  // *build* program that writes a CDP mixfile describing them, then a *render*
  // program that turns that mixfile into one multichannel WAV. The full input
  // list is [srcWav, ...extra.inputs]; templates use '$INS' (the input paths,
  // spread inline), '$MIX' (the mixfile) and '$OUT'.
  if (effect.mixChain) {
    const mc = effect.mixChain;
    const rate = decodeAudio(srcWav).sampleRate;
    const wavs = [srcWav, ...(extra.inputs || [])]
      .map((w) => conformChannels(conformRate(w, rate), mc.inChannels || 'mono'));
    const inPaths = wavs.map((_, i) => `/in${i + 1}.wav`);
    const inputs = {};
    wavs.forEach((w, i) => { inputs[inPaths[i]] = w; });
    const mixPath = `/mix.${mc.ext || 'mmx'}`;
    const expand = (tpl) => tpl.flatMap((a) =>
      a === '$INS' ? inPaths
        : a === '$MIX' ? [mixPath]
          : a === '$OUT' ? ['/out.wav']
            : (a && typeof a === 'object' && a.p != null)
              ? [(a.flag || '') + String(vals[a.p] != null ? vals[a.p] : paramDefault(effect, a.p))]
              : [a]);
    const b = await cdp.run(mc.buildProgram, expand(mc.build), { inputs, outputs: [mixPath] });
    // Stop here if the mixfile stage failed: rendering an empty mixfile buries
    // its error (e.g. a parameter out of the build program's range) under a
    // parse failure from the render program.
    const mix = requireOutput(b, b.outputs[mixPath], mc.buildProgram, 'mixfile');
    const r = await cdp.run(mc.renderProgram, expand(mc.render), { inputs: { [mixPath]: mix, ...inputs }, outputs: ['/out.wav'] });
    return requireOutput(r, r.outputs['/out.wav'], mc.renderProgram);
  }

  // Variadic-input programs (rejoin, ...) take several soundfiles → one output.
  // The full input list is [srcWav, ...extra.inputs]; '$INS' expands to their
  // paths spread inline, '$OUT' is the single output.
  if (effect.variadicInputs) {
    const rate = decodeAudio(srcWav).sampleRate;
    const want = effect.input || null;
    const wavs = [srcWav, ...(extra.inputs || [])]
      .map((w) => { const r = conformRate(w, rate); return want ? conformChannels(r, want) : r; });
    const inPaths = wavs.map((_, i) => `/in${i + 1}.wav`);
    const inputs = { ...brkInputs };
    wavs.forEach((w, i) => { inputs[inPaths[i]] = w; });
    if (staticData != null) inputs['/data.txt'] = new TextEncoder().encode(staticData);
    const mapped = args.flatMap((a) =>
      a === '$INS' ? inPaths : a === '$OUT' ? ['/out.wav'] : a === '$DATA' ? ['/data.txt'] : [a]);
    const res = await cdp.run(effect.program, mapped, { inputs, outputs: ['/out.wav'] });
    return requireOutput(res, res.outputs['/out.wav'], effect.program);
  }

  // Multi-output programs (cantor, isolate, partition, ...) write a *generic*
  // outfile stem and produce several numbered files, so '$OUT' maps to the stem
  // '/out' and the results are collected by prefix. Spectral ones emit numbered
  // .ana files that are each resynthesised to WAV. Returns { outputs, names }.
  if (effect.multiOut) {
    const spectral = effect.domain === 'spectral';
    const src = effect.input ? conformChannels(srcWav, effect.input) : srcWav;
    const inBytes = spectral ? await analyse(cdp, conformChannels(src, 'mono')) : src;
    const inPath = spectral ? '/in.ana' : '/in.wav';
    const ext = spectral ? 'ana' : 'wav';
    const mapped = args.map((a) =>
      a === '$IN' ? inPath : a === '$OUT' ? '/out' : a === '$DATA' ? '/data.txt' : a);
    const inputs = { [inPath]: inBytes, ...brkInputs };
    // The '$DATA' text file is either generated from params (`data`) or derived
    // from the (conformed) source (`derive`, e.g. cut times from its duration).
    const dataStr = effect.derive ? await effect.derive(cdp, src, vals) : staticData;
    if (dataStr != null) inputs['/data.txt'] = typeof dataStr === 'string' ? new TextEncoder().encode(dataStr) : dataStr;
    const res = await cdp.run(effect.program, mapped, {
      // Most multi-output programs write to the '/out' stem; programs that
      // auto-name outputs from the INPUT file (e.g. housekeep chans → in_c1,
      // in_c2, …) override the collect prefix via `effect.collect`.
      inputs, collect: [{ prefix: effect.collect || '/out', ext }],
    });
    // Drop any zero-length files the program left behind when it gave up part
    // way through numbering its outputs.
    const entries = Object.entries(res.outputs).filter(([, bytes]) => bytes && bytes.length);
    if (!entries.length) throw noOutputError(res, effect.program);
    const outputs = [];
    const names = [];
    for (const [path, bytes] of entries) {
      names.push(path.replace(/^\//, '').replace(/\.ana$/, '.wav'));
      outputs.push(spectral
        ? (await cdp.process('pvoc', ['synth', '$IN', '$OUT'], bytes, { inExt: 'ana' })).bytes
        : bytes);
    }
    return { outputs, names };
  }

  if (effect.domain === 'spectral') {
    // Two-input spectral effects (morph, combine, formants vocode) analyse two
    // sounds to .ana, combine them, and resynthesise. Analysis is mono, so the
    // result is mono; `extra.in2` is the second source (defaults to the first).
    if (effect.inputs >= 2) {
      const srcRate = decodeAudio(srcWav).sampleRate;
      const in2 = conformRate(extra.in2 || srcWav, srcRate); // CDP needs matching rates
      const a1 = await analyse(cdp, conformChannels(srcWav, 'mono'));
      const a2 = await analyse(cdp, conformChannels(in2, 'mono'));
      const mapped = args.map((a) => (a === '$IN' ? '/in.ana' : a === '$IN2' ? '/in2.ana' : a === '$OUT' ? '/out.ana' : a));
      const res = await cdp.run(effect.program, mapped, {
        inputs: { '/in.ana': a1, '/in2.ana': a2, ...brkInputs }, outputs: ['/out.ana'],
      });
      const outAna = requireOutput(res, res.outputs['/out.ana'], effect.program);
      return (await cdp.process('pvoc', ['synth', '$IN', '$OUT'], outAna, { inExt: 'ana' })).bytes;
    }
    const pipe = async (mono) => {
      const ana = await cdp.process('pvoc', ['anal', '1', '$IN', '$OUT'], mono, { outExt: 'ana' });
      const out = await cdp.process(effect.program, args, ana.bytes, { inExt: 'ana', outExt: 'ana', data: staticData, extraInputs: brkInputs });
      return (await cdp.process('pvoc', ['synth', '$IN', '$OUT'], out.bytes, { inExt: 'ana' })).bytes;
    };
    return decodeAudio(srcWav).numChannels > 1 ? cdp.eachChannel(srcWav, pipe) : pipe(srcWav);
  }

  // Two sound (time-domain) inputs, e.g. submix.merge: stage both and mix.
  if (effect.inputs >= 2) {
    const src1 = effect.input ? conformChannels(srcWav, effect.input) : srcWav; // e.g. interleave needs mono on BOTH inputs
    let in2 = conformRate(extra.in2 || srcWav, decodeAudio(srcWav).sampleRate); // CDP needs matching rates
    if (effect.in2) in2 = conformChannels(in2, effect.in2); // e.g. subtract requires a mono 2nd input
    const mapped = args.map((a) => (a === '$IN' ? '/in.wav' : a === '$IN2' ? '/in2.wav' : a === '$OUT' ? '/out.wav' : a));
    const res = await cdp.run(effect.program, mapped, {
      inputs: { '/in.wav': src1, '/in2.wav': in2, ...brkInputs }, outputs: ['/out.wav'],
    });
    return requireOutput(res, res.outputs['/out.wav'], effect.program);
  }

  // Spatialisation / fixed-input effects: conform the source to the required
  // channel layout (the program decides the output layout), no per-channel split.
  if (effect.input) {
    const conformed = conformChannels(srcWav, effect.input);
    const data = effect.derive ? await effect.derive(cdp, conformed, vals) : staticData;
    const res = await cdp.process(effect.program, args, conformed, { data, extraInputs: brkInputs });
    return res.bytes;
  }

  const data = effect.derive ? await effect.derive(cdp, srcWav, vals) : staticData;
  const res = await cdp.process(effect.program, args, srcWav, { channels: effect.mono ? 'split' : undefined, data, extraInputs: brkInputs });
  return res.bytes;
}

/** The `{ dur, srate, chans, in2? }` a run's ranges and defaults are measured against. */
function sourceContext(srcWav, extra) {
  const info = (wav) => {
    const d = decodeAudio(wav);
    return { dur: d.length / d.sampleRate, srate: d.sampleRate, chans: d.numChannels };
  };
  const src = info(srcWav);
  if (extra && extra.in2) src.in2 = info(extra.in2);
  return src;
}

// conformChannels/conformRate live with the shared helpers (entry closures in
// catalog/ need them too); re-exported here so the public surface is unchanged.
export { conformChannels, conformRate };
